# Analyze all changes systematically
inputs = ['jbgw', 'bcc', 'dzffaf', 'kizwey', 'fuyc']
outputs = ['jbgzkw', 'bz', 'dzffaf', 'iuyizwey', 'fuycwd']

print("Detailed analysis of each change:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"\n{i}: '{inp}' -> '{outp}'")

    if inp != outp:
        # Find minimal edit
        min_len = min(len(inp), len(outp))
        pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                pos = j
                break

        if pos == -1:
            # One string is prefix of other
            if len(inp) < len(outp):
                pos = len(inp)
                print(f"  Append '{outp[pos:]}' at position {pos}")
            else:
                print(f"  Remove '{inp[pos:]}' from position {pos}")
        else:
            # Find what's being replaced
            old_char = inp[pos]
            # Find how much was replaced
            old_end = pos + 1
            new_end = pos + 1

            # Look ahead to see what we're replacing
            while old_end <= len(inp) and new_end <= len(outp):
                if inp[pos:old_end] == outp[pos:new_end]:
                    old_end += 1
                    new_end += 1
                else:
                    break

            old_sub = inp[pos:old_end-1]
            new_sub = outp[pos:new_end-1]
            print(f"  Replace '{old_sub}' with '{new_sub}' at position {pos}")
    else:
        print("  No change")

